create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null default '', email text, role text not null default 'CUSTOMER' check (role in ('CUSTOMER','STAFF','ADMIN')), created_at timestamptz not null default now());
create table if not exists public.cars (id uuid primary key default gen_random_uuid(), make text not null, model text not null, year int not null, price_kes numeric not null, price_usd numeric, range_km int, battery_kwh numeric, availability text not null default 'In Stock', location text, specs jsonb not null default '{}'::jsonb, photo_url text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.enquiries (id uuid primary key default gen_random_uuid(), name text not null, email text not null, country text, vehicle text, budget text, notes text, status text not null default 'NEW', created_at timestamptz not null default now());
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), name text, email text, subject text, message text not null, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.cars enable row level security; alter table public.enquiries enable row level security; alter table public.messages enable row level security;
drop policy if exists cars_public_read on public.cars; create policy cars_public_read on public.cars for select using (is_active = true or exists (select 1 from public.profiles p where p.id=auth.uid() and p.role in ('ADMIN','STAFF')));
drop policy if exists enquiries_public_insert on public.enquiries; create policy enquiries_public_insert on public.enquiries for insert with check (true);
drop policy if exists messages_public_insert on public.messages; create policy messages_public_insert on public.messages for insert with check (true);
insert into public.cars (make,model,year,price_kes,price_usd,range_km,battery_kwh,availability,location,specs) select * from (values ('BYD','Dolphin',2025,2100000,14500,405,60.4,'In Stock','Nairobi','{"drive":"FWD","charging":"DC fast charge"}'::jsonb),('BYD','Atto 3',2025,2500000,17200,480,60.5,'In Transit','Mombasa','{"drive":"FWD","charging":"DC fast charge"}'::jsonb),('Neta','V',2025,1800000,12400,401,40.7,'Pre-Order','Nairobi','{"drive":"FWD","charging":"AC/DC"}'::jsonb)) v(make,model,year,price_kes,price_usd,range_km,battery_kwh,availability,location,specs) where not exists (select 1 from public.cars);
insert into storage.buckets (id,name,public) values ('car-photos','car-photos',true) on conflict (id) do nothing;
